	["Kill monsters in Garona Forest."] = "Mata monstruos en el Bosque de Garona.",
	["Clean the rat plague before they reach the city!"] = "¡Limpia la plaga de ratas antes de que lleguen a la ciudad!",
	["Protect the lost girl from the monsters."] = "Protege a la niña perdida de los monstruos.",
	["Doppelgangers are invading the Hidden Temple!"] = "¡Los doppelgangers están invadiendo el Templo Oculto!",
	["Collect sacrifices from the beasts and deliver them to the altar!"] = "¡Recolecta sacrificios de las bestias y entrégalos al altar!",
	["Doppelgangers are invading the Emberwild Catacombs!"] = "¡Los doppelgangers están invadiendo las Catacumbas de Emberwild!",
	["A rift has opened on Bone Beach!"] = "¡Se ha abierto una grieta en la Playa de Huesos!",
	["Historical memories have appeared in the Bone Deeps!"] = "¡Han aparecido recuerdos históricos en las Profundidades de Huesos!",
	["Kill 200 monsters in Inferna's Island."] = "Mata 200 monstruos en la Isla de Inferna.",
	["Defeat sarandel the old ash ."] = "Derrota a Sarandel el Viejo Ceniza.",
	["Defeat the invasion!"] = "¡Derrota la invasión!",
	["Kill 200 monsters in Iceborn Fields."] = "Mata 200 monstruos en los Campos Gélidos.",
