	["east from gaelia"] = "al este de Gaelia",
	["The relic lays within the mines."] = "La reliquia yace dentro de las minas.",
	["Garnak the Warlord is hiding deep within the Mining excavation."] = "Garnak el Señor de la Guerra se esconde en lo profundo de la excavación minera.",
	["Seek out the three Ancient Seals deep in Shadow Hollow and activate them."] = "Busca los tres Sellos Antiguos en lo profundo de Shadow Hollow y actívalos.",
	["Vael the Betrayer lurks in the deepest part of Shadow Hollow."] = "Vael el Traidor acecha en la parte más profunda de Shadow Hollow.",
	["The Outcast Elf hides east deep in the woods, away from his kin."] = "El Elfo Desterrado se esconde al este, en lo profundo del bosque, lejos de los suyos.",
	["The relics are held by Elven Ritualists deep within the Verdant Grove."] = "Las reliquias están en poder de Ritualistas Élficos en lo profundo del Verdant Grove.",
	["The exiled Elven High Priest Saranor performs dark rituals in the heart of the forest."] = "El exiliado Sumo Sacerdote Élfico Saranor realiza rituales oscuros en el corazón del bosque.",
	["The sacred basin lies on the second floor of the shrine in Vendel Pass."] = "La fuente sagrada está en el segundo piso del santuario de Vendel Pass.",
	["woodcutting required"] = "se requiere tala de madera",
	["Accept the quest from Darian, then find the red rose nearby and place it on Elyria's grave."] = "Acepta la misión de Darian, luego encuentra la rosa roja cercana y colócala sobre la tumba de Elyria.",
	["Take the Cursed Signet from Darian and drop it into the enchanted witch's cauldron in the Cursed Cemetery."] = "Toma el Sello Maldito de Darian y échalo en el caldero encantado de la bruja en el Cementerio Maldito.",
	["somewhere inside the Dark Cathedral"] = "en algún lugar dentro de la Catedral Oscura",
	["The Blood Flower Seal binds Lily somewhere deep inside the Forgotten Library."] = "El Sello de la Flor de Sangre retiene a Lily en algún lugar profundo de la Biblioteca Olvidada.",
	["somehere inside the Forgotten Library"] = "en algún lugar dentro de la Biblioteca Olvidada",
	["The letter is locked within the ruined house, waiting to be found."] = "La carta está encerrada en la casa en ruinas, esperando ser encontrada.",
	["The mirror lies shattered in the Forgotten Library, yet its reflection lingers."] = "El espejo yace destrozado en la Biblioteca Olvidada, pero su reflejo permanece.",
	["Merchant Tobias owes Garrek 4 gold ingots. Retrieve the debt."] = "El mercader Tobias le debe a Garrek 4 lingotes de oro. Recupera la deuda.",
	["Find the marked grave in the Graveyard of the Lost and dig up the 'heirloom'."] = "Encuentra la tumba marcada en el Cementerio de los Perdidos y desentierra la 'herencia'.",
	["Dig carefully. You might wake something up."] = "Cava con cuidado. Podrías despertar algo.",
	["Find a way to put the spirit to rest before Gerald loses his mind."] = "Encuentra la manera de dar descanso al espíritu antes de que Gerald pierda la cabeza.",
	["Find the Lily's coffin in the last flor of the Forgotten Library and free lily."] = "Encuentra el ataúd de Lily en el último piso de la Biblioteca Olvidada y libera a Lily.",
	["Malrith lurks in the depths of the Forgotten Library, waiting to devour all who dare to face him."] = "Malrith acecha en las profundidades de la Biblioteca Olvidada, esperando devorar a quien se atreva a enfrentarlo.",
	["Step into the fog south of the village and listen carefully."] = "Adéntrate en la niebla al sur de la aldea y escucha con atención.",
	["Seek out Edwin's gravestone inside the Eldenmere Ruins"] = "Busca la lápida de Edwin dentro de las Ruinas de Eldenmere",
	["Seek out Seraphine's gravestone inside the Eldenmere Ruins."] = "Busca la lápida de Seraphine dentro de las Ruinas de Eldenmere.",
	["Seek out Marek's gravestone inside the Eldenmere Ruins."] = "Busca la lápida de Marek dentro de las Ruinas de Eldenmere.",
	["Channel energy into the spectral braziers while surviving Marek's fury."] = "Canaliza energía en los braseros espectrales mientras sobrevives a la furia de Marek.",
	["Find the Guardian of the Forgotten in the Sealed Crypt and speak the names of the lost (Edwin, Seraphine, Marek) to complete the ritual."] = "Encuentra al Guardián de los Olvidados en la Cripta Sellada y pronuncia los nombres de los perdidos (Edwin, Seraphine, Marek) para completar el ritual.",
	["Collect spores scattered from fungal creatures."] = "Recolecta las esporas que sueltan las criaturas fúngicas.",
	["investigate the tunnels beneath the Sporeveil Outskirts."] = "investiga los túneles bajo las Afueras de Sporeveil.",
	["Search the lower tunnels beneath the swamp to uncover the secrets of the ancient machine."] = "Busca en los túneles inferiores bajo el pantano para descubrir los secretos de la máquina antigua.",
	["The Fungal Sentinel is said to guard the lower roots beneath the swamp machinery."] = "Se dice que el Centinela Fúngico vigila las raíces inferiores bajo la maquinaria del pantano.",
	["Bloomheart resides in the fungal bloom chamber near the heart of the machine's energy well."] = "Bloomheart reside en la cámara de floración fúngica, cerca del corazón del pozo de energía de la máquina.",
	["Seek out the 4 power stones and stabilize their energy underground."] = "Busca las 4 piedras de poder y estabiliza su energía bajo tierra.",
	["Find and activate the Sporegate control mechanism."] = "Encuentra y activa el mecanismo de control del Sporegate.",
	["Step into the Sporegate and explore what lies beyond."] = "Atraviesa el Sporegate y explora lo que hay al otro lado.",
	["Watch out for cows that growl or have red eyes!"] = "¡Cuidado con las vacas que gruñen o tienen ojos rojos!",
	["ask Farmer Cluckington for a broom to hit chickens and make them hatch!"] = "¡pídele una escoba al granjero Cluckington para golpear a las gallinas y hacerlas eclosionar!",
	["lure and Move Lost sheep inside Mercenary Camp."] = "atrae y guía a las ovejas perdidas dentro del Campamento de Mercenarios.",
	["Type 'haha', 'lol', or 'laugh' after each joke - even if it hurts. Phil's ego is more fragile than his straw stuffing."] = "Escribe 'haha', 'lol' o 'laugh' después de cada chiste, aunque duela. El ego de Phil es más frágil que su relleno de paja.",
	["Search for traces of the goblin stash and signs of Vornik's fate."] = "Busca rastros del escondite goblin y señales del destino de Vornik.",
	["Slay any goblins you find in the mountain pass. Lucy wants no survivors."] = "Mata a todos los goblins que encuentres en el paso de montaña. Lucy no quiere supervivientes.",
	["Search crates, barrels, or goblin bosses for their treasure stash."] = "Busca en cajas, barriles o jefes goblin su tesoro escondido.",
	["Grizzltooth commands the goblins from deep within their northern throne room."] = "Grizzltooth comanda a los goblins desde lo profundo de su sala del trono del norte.",
	["look at the distance using the telescope at the upper floors."] = "observa la distancia usando el telescopio de los pisos superiores.",
	["find a book related to this language inside the library."] = "encuentra un libro relacionado con este idioma dentro de la biblioteca.",
	["Climb Wyrmfang Mountain and find the hermit's cave. Be wary the wyrms do not sleep."] = "Escala la Montaña Wyrmfang y encuentra la cueva del ermitaño. Cuidado: los wyrms no duermen.",
	["Search the eastern tunnels of the Wyrmfang caves and cull the wyrms that dwell within."] = "Busca en los túneles orientales de las cuevas de Wyrmfang y extermina a los wyrms que allí habitan.",
	["investigate the trolls."] = "investiga a los trolls.",
	["Talk to tribe members across the troll encampment. Not everyone trusts Rukk."] = "Habla con los miembros de la tribu por el campamento troll. No todos confían en Rukk.",
	["Gor'mhaz hides himself, kill his People to force him out."] = "Gor'mhaz se esconde: mata a su gente para obligarlo a salir.",
	["Relics glow faintly near sacred troll grounds."] = "Las reliquias brillan tenuemente cerca de los terrenos sagrados de los trolls.",
	["kill Gor'mhaz people to force him out."] = "mata a la gente de Gor'mhaz para obligarlo a salir.",
	["Inspect the circle and fallen bodies. Rukk's truth is etched in shadow."] = "Inspecciona el círculo y los cuerpos caídos. La verdad de Rukk está grabada en la sombra.",
	["Confront Rukk at the altar before the ritual completes."] = "Enfrenta a Rukk en el altar antes de que se complete el ritual.",
	["Speak with Salim the Lookout in the ruined fortress at the volcano entrance. Find Draya the Waterkeeper deep inside the volcano."] = "Habla con Salim el Vigía en la fortaleza en ruinas junto a la entrada del volcán. Encuentra a Draya la Guardiana del Agua en lo profundo del volcán.",
	["This quests is not finished."] = "Esta misión no está terminada.",
	["The camels love honeycombs."] = "A los camellos les encantan los panales.",
	["Check the eastern banks of the oasis during or after a sandstorm."] = "Revisa las orillas orientales del oasis durante o después de una tormenta de arena.",
	["Hunt desert draptors near the scorched cliffs west of the oasis."] = "Caza draptors del desierto cerca de los acantilados calcinados al oeste del oasis.",
	["Search the lowest levels of the western catacombs. The crate may still be near a collapsed hallway."] = "Busca en los niveles más bajos de las catacumbas occidentales. La caja puede seguir cerca de un pasillo derrumbado.",
	["Visit nearby camps and ask for volunteers willing to fight for the mountain."] = "Visita los campamentos cercanos y pide voluntarios dispuestos a luchar por la montaña.",
	["Blacksmith"] = "Herrero",
	["Search the ogre side of the battlefield for bone piles and discarded gear."] = "Busca en el lado ogro del campo de batalla montones de huesos y equipo abandonado.",
	["Search near camp supplies, the buildings, and the upper road wich leads to the ogre camp for marks of sabotage."] = "Busca marcas de sabotaje cerca de los suministros del campamento, los edificios y el camino superior que lleva al campamento ogro.",
	["Khurzug's throne lies deep in the heart of the ogre stronghold to the south. Be prepared for a brutal fight."] = "El trono de Khurzug está en el corazón de la fortaleza ogro al sur. Prepárate para una pelea brutal.",
	["Perform tasks, favors, or dirty deeds around Deadfin Port to build enough reputation to be considered a local."] = "Realiza tareas, favores o trabajos sucios por Deadfin Port para ganar reputación suficiente y ser considerado un local.",
	["Step on plates with yellow hazard paint near major pipe elbows."] = "Pisa las placas con pintura amarilla de peligro cerca de los codos principales de las tuberías.",
	["Check racks and benches marked with hazard signs."] = "Revisa los estantes y bancos marcados con señales de peligro.",
	["Faint green luminescence marks the plates in deep corridors."] = "Una luminiscencia verde tenue marca las placas en los corredores profundos.",
	["Defeat the Rustheart Node and claim a fragment of its core."] = "Derrota al Rustheart Node y reclama un fragmento de su núcleo.",
	["Blue-tagged valve wheels mark inspection points."] = "Las ruedas de válvula con etiqueta azul marcan los puntos de inspección.",
	["Hunt near half-buried pipes and scaffolds."] = "Caza cerca de las tuberías semienterradas y los andamios.",
	["Priming plates are wired to the access gantry."] = "Las placas de cebado están cableadas a la pasarela de acceso.",
	["Defeat the Overmind Mycogear and claim its overcore."] = "Derrota al Overmind Mycogear y reclama su supernúcleo.",
	["Find the bone organ inside the cathedral and play the final chord."] = "Encuentra el órgano de hueso dentro de la catedral y toca el acorde final.",
	["Use the secret passage in the cathedral to reach the crypt and defeat The Penitent Knight."] = "Usa el pasadizo secreto de la catedral para llegar a la cripta y derrotar al Caballero Penitente.",
	["Kill spiders to force The Old Widow to appear."] = "Mata arañas para obligar a la Viuda Anciana a aparecer.",
	["Speak with the juror spirits and collect each testimony about the murder night."] = "Habla con los espíritus jurado y recoge cada testimonio sobre la noche del asesinato.",
	["Search the Black Mire for the hidden witness who holds the Tide's Confession."] = "Busca en la Ciénaga Negra al testigo oculto que guarda la Confesión de la Marea.",
	["Return to Magistrate Corvin, share the Tide's Confession, and choose the final verdict."] = "Regresa con el Magistrado Corvin, comparte la Confesión de la Marea y elige el veredicto final.",
	["Speak to Gravedigger Neral to learn the candle order. Then light the Name, the Oath, and the Rest in the Flooded Crypt."] = "Habla con el Sepulturero Neral para aprender el orden de las velas. Luego enciende el Nombre, el Juramento y el Descanso en la Cripta Inundada.",
	["Speak to Djinn Chronicler Zahim to learn the order. Then activate the five brass lamps in the labyrinth without breaking the sequence."] = "Habla con el Cronista Djinn Zahim para aprender el orden. Luego activa las cinco lámparas de latón del laberinto sin romper la secuencia.",
	["Use the north hidden altar to open a temporary teleport into Marid's chamber."] = "Usa el altar oculto del norte para abrir un teletransporte temporal a la cámara de Marid.",
	["Defeat Marid to seal your victory."] = "Derrota a Marid para sellar tu victoria.",
	["Speak with Kael Frostward, then climb the Dragon Mountain to recover the three Frozen Memory Shards."] = "Habla con Kael Frostward y luego escala la Montaña del Dragón para recuperar los tres Fragmentos de Memoria Congelada.",
	["Speak with Elira, then enter the Frozen Castle (zone 68). Slay 12 Iceborn Sentinels and read the Frozen Chronicle."] = "Habla con Elira y luego entra en el Castillo Congelado (zona 68). Mata 12 Sentinelas Gélidos y lee la Crónica Congelada.",
	["Speak with Elira after completing The Frozen Castle. Enter the Shadow Realm dungeon, destroy 8 Shadows of Dreadmaw, and defeat Dreadmaw himself to break the seal on the Frostbound Heart."] = "Habla con Elira tras completar El Castillo Congelado. Entra en la mazmorra del Reino de las Sombras, destruye 8 Sombras de Dreadmaw y derrota al propio Dreadmaw para romper el sello del Corazón Escarchado.",
	["Speak with Salim the Lookout in the ruined fortress at the volcano entrance. Relight the three beacons scattered around the volcano."] = "Habla con Salim el Vigía en la fortaleza en ruinas junto a la entrada del volcán. Reenciende las tres balizas dispersas por el volcán.",
	["Speak with Salim the Lookout in the ruined fortress. Find his scouting party's logbook on the right side of the island."] = "Habla con Salim el Vigía en la fortaleza en ruinas. Encuentra el cuaderno de bitácora de su grupo de exploración en el lado derecho de la isla.",
	["Speak with Cinder Witch Velka. Touch the three cinder sigils hidden around the volcano."] = "Habla con la Bruja de la Ceniza Velka. Toca los tres sigilos de brasa ocultos alrededor del volcán.",
	["Speak with Cinder Witch Velka after completing Embers of the Old Faith. Rekindle the ancient forge and fill the volcanic crucible."] = "Habla con la Bruja de la Ceniza Velka tras completar Brasas de la Antigua Fe. Reaviva la forja ancestral y llena el crisol volcánico.",
	["Speak with Cinder Witch Velka after completing The Cinder Brand. Read the two volcanic inscriptions hidden in the depths."] = "Habla con la Bruja de la Ceniza Velka tras completar La Marca de la Ceniza. Lee las dos inscripciones volcánicas ocultas en las profundidades.",
	["Enter the Dragon's Den and slay Sarandel's wyrms until the nest is threatened. The Old Ash will rise only when he senses real danger."] = "Entra en la Guarida del Dragón y mata a los wyrms de Sarandel hasta que el nido se sienta amenazado. El Viejo Ceniza solo se alzará cuando perciba un peligro real.",
	["Speak with Ash-Touched Varrick after completing Dragon's Den. Defeat Sarandel, the Old Ash, and the wyrmward will break with him."] = "Habla con Varrick Tocado por la Ceniza tras completar la Guarida del Dragón. Derrota a Sarandel, el Viejo Ceniza, y la protección wyrm se romperá con él.",
	["Speak with Salim the Lookout. Hunt Dragons and Elder Dragons on Inferna's Island and bring him green and red dragon scales."] = "Habla con Salim el Vigía. Caza Dragones y Dragones Ancianos en la Isla de Inferna y tráele escamas de dragón verdes y rojas.",
	["Find the scorched wyrm egg deep in the volcano and use it. The action is marked on the egg."] = "Encuentra el huevo de wyrm chamuscado en lo profundo del volcán y úsalo. La acción está marcada en el huevo.",
	["Find Sarandel's hoard. It is sealed by a secret code, and someone on the island still remembers it."] = "Encuentra el tesoro de Sarandel. Está sellado por un código secreto, y alguien en la isla aún lo recuerda.",
