	["witnesses"] = "testigos",
	["Four priming plates feed the gantry. Touch them in any order. If the floor hums, you’re doing it right."] = "Cuatro placas de cebado alimentan la pasarela. Tócalas en cualquier orden. Si el suelo zumba, lo estás haciendo bien.",
	["I’ve lived on Wyrmfang Mountain for decades. These creatures are ancient and proud. If they rise, something has disturbed their slumber."] = "He vivido en la Montaña Wyrmfang durante décadas. Estas criaturas son antiguas y orgullosas. Si se alzan, algo perturbó su sueño.",
	["Listen... I think that corpse wasn’t as 'lifeless' as I thought. I keep seeing things. I think it's haunting me! Please, do something!"] = "Escucha... creo que ese cadáver no estaba tan 'inerte' como pensaba. Sigo viendo cosas. ¡Creo que me persigue! ¡Por favor, haz algo!",
	["Systems idle. Primers cold. If you’re brave, we can fix that. What do you need?"] = "Sistemas inactivos. Cebadores fríos. Si eres valiente, podemos arreglarlo. ¿Qué necesitas?",
	["Three valves, main line. Tag them, check the gauges. If it screams, you’re turning it right."] = "Tres válvulas, línea principal. Márcalas, revisa los manómetros. Si chilla, la estás girando bien.",
	["Valves sing when the pressure’s right. We keep the line alive or the swamp eats us. Want the rundown?"] = "Las válvulas cantan cuando la presión es la correcta. Mantenemos la línea viva o el pantano nos devora. ¿Quieres el resumen?",
	["Welcome! Looking for fine goods? We’ve got the best deals in town."] = "¡Bienvenido! ¿Buscas mercancía fina? Tenemos las mejores ofertas de la ciudad.",
	["You dare try to fool me?! I know a fake when I smell one! You’ll regret this."] = "¡¿Te atreves a engañarme?! ¡Sé reconocer una falsificación cuando la huelo! Te arrepentirás de esto.",
	["You hear them, don’t you? Beneath the sands. The wyrms have begun to stir... and they do not stir without reason."] = "Los oyes, ¿verdad? Bajo las arenas. Los wyrms han comenzado a agitarse... y no se agitan sin razón.",
	["You’ve faced them and lived. I thank you. But this is just the beginning, mark my words."] = "Los enfrentaste y viviste. Te lo agradezco. Pero esto es solo el principio, recuerda mis palabras.",
	["The tunnels northeast of here… they reek of fear and blood. If you’re brave enough, go there and drive the wyrms back."] = "Los túneles al noreste de aquí huelen a miedo y a sangre. Si eres lo bastante valiente, ve allí y haz retroceder a los wyrms.",
	["Enemies reduce the first hit received every 5s by 80%."] = "Los enemigos reducen el primer golpe recibido cada 5s en un 80%.",
	["Crystal Cave"] = "Cueva de Cristal",

	["*cough* |PLAYERNAME|... please... help me..."] = "*tos* |PLAYERNAME|... por favor... ayudame...",
	["Achievements await!"] = "Los logros esperan!",
	["Ah, |PLAYERNAME|... the dead whisper your name. Are you here for my {quests}?"] = "Ah, |PLAYERNAME|... los muertos susurran tu nombre. ¿Vienes por mis {quests}?",
	["Ahoy, sailor!"] = "Ahoy, marinero!",
	["Be LEGENDARY!"] = "Se LEGENDARIO!",
	["Be careful down there..."] = "Ten cuidado ahi abajo...",
	["Before dawn, they rushed the sentence."] = "Antes del amanecer, apresuraron la sentencia.",
	["Blessings upon you."] = "Bendiciones sobre ti.",
	["Bring me the sacrifices offered by the fallen, and I shall reward your devotion."] = "Traeme los sacrificios ofrecidos por los caidos y recompensare tu devocion.",
	["Bzzzz! Welcome!"] = "Bzzzz! Bienvenido!",
	["COME BACK WHEN YOU ARE PREPARED TO FACE YOUR DESTINY!"] = "VUELVE CUANDO ESTES PREPARADO PARA ENFRENTAR TU DESTINO!",
	["Carry my words to the court."] = "Lleva mis palabras a la corte.",
	["Carry the truth lightly, or it will drown you too."] = "Lleva la verdad con ligereza, o te hundira tambien.",
	["Chains rust, but guilt does not."] = "Las cadenas se oxidan, pero la culpa no.",
	["Daily quests ready!"] = "Misiones diarias listas!",
	["Do not break the sequence."] = "No rompas la secuencia.",
	["Do not let fear judge again."] = "No dejes que el miedo juzgue de nuevo.",
	["Don't leave me here..."] = "No me dejes aqui...",
	["Don't wake the egg."] = "No despiertes el huevo.",
	["Dont Die!"] = "No mueras!",
	["Feed them well!"] = "Alimentalos bien!",
	["Feeling lucky?"] = "¿Te sientes con suerte?",
	["Fine!"] = "Bien!",
	["Fortune favors the bold!"] = "La fortuna favorece a los audaces!",
	["Fresh food for pets!"] = "Comida fresca para mascotas!",
	["Good day."] = "Buen dia.",
	["Good luck with your pulls!"] = "Buena suerte con tus tiradas!",
	["Greetings, champion. Let us speak of prestige."] = "Saludos, campeon. Hablemos de prestigio.",
	["Greetings, commoner."] = "Saludos, plebeyo.",
	["Greetings, researcher!"] = "Saludos, investigador!",
	["Greetings, traveler. I sense great power within you."] = "Saludos, viajero. Siento un gran poder dentro de ti.",
	["Happy cooking!"] = "Feliz cocina!",
	["Happy trading!"] = "Feliz comercio!",
	["Hello |PLAYERNAME|! I am Cedric, the Stash Keeper. I can help you manage your {supply stash}."] = "Hola |PLAYERNAME|! Soy Cedric, el Guardián del Almacen. Puedo ayudarte a gestionar tu {supply stash}.",
	["Hello |PLAYERNAME|. I sell runes, potions, wands and rods."] = "Hola |PLAYERNAME|. Vendo runas, pociones, varitas y bastones.",
	["Here. Don't forget that you need to buy a label too if you want to send a parcel. Always write the name of the {receiver} in the first line."] = "Aqui. No olvides que tambien necesitas comprar una etiqueta si quieres enviar un paquete. Siempre escribe el nombre del {receiver} en la primera linea.",
	["Hey there! Want to know about the Pet Capsule Machine?"] = "Hola! ¿Quieres saber sobre la Maquina de Capsulas de Mascotas?",
	["Hi |PLAYERNAME|, are u interested in some of my {quests} or maybe {rewards}"] = "Hola |PLAYERNAME|, ¿te interesan mis {quests} o quiza {rewards}?",
	["I have buried more hunters than the volcano has claimed. Speak carefully, or join them."] = "He enterrado mas cazadores de los que el volcan ha cobrado. Habla con cuidado o unete a ellos.",
	["I remember the dock... and the lie they called truth."] = "Recuerdo el muelle... y la mentira que llamaron verdad.",
	["Is |TOTALCOST| gold coins too much for you? Get out of here!"] = "¿|TOTALCOST| monedas de oro es demasiado para ti? Fuera de aqui!",
	["Keep achieving!"] = "Sigue logrando!",
	["Keep crawling around!"] = "Sigue reptando por ahi!",
	["Keep your pick sharp!"] = "Manten tu pico afilado!",
	["Legends await!"] = "Las leyendas esperan!",
	["Let daylight reach the record."] = "Que la luz del dia alcance el registro.",
	["Let the elements protect you."] = "Que los elementos te protejan.",
	["May colors brighten your path!"] = "Que los colores iluminen tu camino!",
	["May darkness embrace you..."] = "Que la oscuridad te abrace...",
	["May fortune favor you!"] = "Que la fortuna te favorezca!",
	["May light guide your path."] = "Que la luz guie tu camino.",
	["May magic flow through you!"] = "Que la magia fluya a traves de ti!",
	["May myths guide you!"] = "Que los mitos te guien!",
	["May the arcane guide you!"] = "Que lo arcano te guie!",
	["May the tides guide you!"] = "Que las mareas te guien!",
	["May the water not drown your judgment."] = "Que el agua no ahogue tu juicio.",
	["May the woods shelter you!"] = "Que el bosque te cobije!",
	["May your name remain unbound."] = "Que tu nombre permanezca libre.",
	["May your path be fragrant!"] = "Que tu camino sea fragante!",
	["May your sentence be just."] = "Que tu sentencia sea justa.",
	["Nature calls!"] = "La naturaleza llama!",
	["Only the ELITE!"] = "Solo la ELITE!",
	["Protect the wild!"] = "Protege lo salvaje!",
	["Quiet now. The dead only speak when the Three Tallow Names burn in order."] = "Silencio ahora. Los muertos solo hablan cuando los Tres Nombres de Sebo arden en orden.",
	["Rarities await, collector."] = "Las rarezas esperan, coleccionista.",
	["Ready to trade?"] = "¿Listo para comerciar?",
	["Roots whisper. If you listen, they guide the blade. Seeking quests?"] = "Las raices susurran. Si escuchas, guian la hoja. ¿Buscas misiones?",
	["STEP RIGHT UP!"] = "PASEN ADELANTE!",
